INSERT INTO course_revisions (id, course_id, status, title, summary, difficulty, estimated_minutes, lesson_count, submitted_at, published_at, created_at, updated_at) VALUES
    (UUID_TO_BIN('01a1e004-0000-7000-8000-200000000001'), UUID_TO_BIN('01a1e004-0000-7000-8000-100000000001'), 'PUBLISHED', 'SQL 4: Truy vấn lồng', 'Dùng kết quả của một truy vấn bên trong truy vấn khác.\n- Subquery trả một giá trị trong WHERE và SELECT\n- IN, NOT IN và bẫy NULL, so sánh với ANY và ALL\n- Subquery tương quan, EXISTS và NOT EXISTS\n- Bảng dẫn xuất: tính trước, lọc sau\n- Chọn giữa JOIN, subquery và EXISTS', 'MEDIUM', 130, 11, '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000')
INSERT INTO chapters (id, revision_id, title, position, created_at, updated_at) VALUES
    (UUID_TO_BIN('01a1e004-0000-7000-8000-300000000001'), UUID_TO_BIN('01a1e004-0000-7000-8000-200000000001'), 'Subquery trả một giá trị', 1, '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e004-0000-7000-8000-300000000002'), UUID_TO_BIN('01a1e004-0000-7000-8000-200000000001'), 'Subquery trả một danh sách', 2, '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e004-0000-7000-8000-300000000003'), UUID_TO_BIN('01a1e004-0000-7000-8000-200000000001'), 'Subquery tương quan và EXISTS', 3, '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e004-0000-7000-8000-300000000004'), UUID_TO_BIN('01a1e004-0000-7000-8000-200000000001'), 'Subquery trong FROM', 4, '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000');
INSERT INTO lessons (id, chapter_id, lesson_key, slug, title, body, position, estimated_minutes, created_at, updated_at) VALUES
    (UUID_TO_BIN('01a1e004-0000-7000-8000-400000000001'), UUID_TO_BIN('01a1e004-0000-7000-8000-300000000001'), UUID_TO_BIN('01a1e004-0000-7000-8000-500000000001'), 'subquery-la-gi', 'Subquery là gì', '## Câu hỏi cần hai bước\n\n> Những sản phẩm nào đắt hơn giá trung bình?\n\nBước 1, tính giá trung bình:\n\n```sql\nSELECT AVG(price) FROM products;\n```\n\nBước 2, so với con số đó. Thay vì chép tay con số, đặt nguyên câu bước 1 vào trong ngoặc:\n\n```sql\nSELECT name, price\nFROM products\nWHERE price > (SELECT AVG(price) FROM products)\nORDER BY price DESC;\n```\n\nCâu trong ngoặc gọi là **subquery** (truy vấn con). Nó chạy trước và kết quả được dùng như một giá trị bình thường. Giá trung bình là khoảng 7,39 triệu, kết quả có 6 sản phẩm.\n\n## Vì sao không viết WHERE price > AVG(price)\n\nHàm tổng hợp không dùng được trong WHERE: WHERE xét từng dòng, còn AVG cần cả bảng. Subquery tách việc tính trung bình ra thành một bước riêng.\n\n## Subquery đặt được ở đâu\n\n- Trong `WHERE` và `HAVING`: so sánh với một giá trị hay một danh sách.\n- Trong `SELECT`: thêm một cột tính riêng cho mỗi dòng.\n- Trong `FROM`: dùng kết quả như một bảng tạm.\n\nCác bài tiếp theo đi qua từng chỗ.\n\n## Thử ngay\n\nÔ dưới tìm nhân viên lương cao hơn trung bình toàn công ty.', 1, 10, '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e004-0000-7000-8000-400000000002'), UUID_TO_BIN('01a1e004-0000-7000-8000-300000000001'), UUID_TO_BIN('01a1e004-0000-7000-8000-500000000002'), 'so-sanh-voi-gia-tri-tong-hop', 'So sánh với MAX, MIN và giá trị của dòng khác', '## Dòng có giá trị lớn nhất\n\n> Sản phẩm đắt nhất là gì?\n\n```sql\nSELECT name, price\nFROM products\nWHERE price = (SELECT MAX(price) FROM products);\n```\n\nKhác với `ORDER BY price DESC LIMIT 1`, cách này trả **mọi** sản phẩm cùng giá cao nhất nếu có hoà.\n\n## So với giá trị của một dòng cụ thể\n\n> Những nhân viên vào làm sau Hồ Vân.\n\n```sql\nSELECT name, hire_date\nFROM employees\nWHERE hire_date > (SELECT hire_date FROM employees WHERE name = ''Hồ Vân'')\nORDER BY hire_date;\n```\n\n## Subquery phải trả đúng một giá trị\n\nDùng với `=`, `>`, `<`, subquery phải trả **tối đa một dòng một cột**. Nếu trả nhiều dòng, PostgreSQL báo lỗi *more than one row returned by a subquery used as an expression*:\n\n```sql\n-- lỗi: có nhiều nhân viên phòng Kỹ thuật\nSELECT name\nFROM employees\nWHERE salary > (SELECT salary FROM employees WHERE department = ''Kỹ thuật'');\n```\n\nNếu subquery không trả dòng nào, nó cho NULL và phép so sánh không bao giờ đúng.\n\n## Thử ngay\n\nÔ dưới tìm đơn hàng có ngày đặt gần nhất. Thử đổi sang ngày sớm nhất.', 2, 12, '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e004-0000-7000-8000-400000000003'), UUID_TO_BIN('01a1e004-0000-7000-8000-300000000001'), UUID_TO_BIN('01a1e004-0000-7000-8000-500000000003'), 'subquery-trong-select', 'Subquery trong SELECT', '## Thêm một cột tính sẵn\n\nSubquery một giá trị có thể đứng trong SELECT như một cột:\n\n```sql\nSELECT name, price,\n       (SELECT ROUND(AVG(price)) FROM products) AS avg_price,\n       price - (SELECT ROUND(AVG(price)) FROM products) AS diff_from_avg\nFROM products\nORDER BY diff_from_avg DESC;\n```\n\nMỗi dòng có thêm giá trung bình để so sánh.\n\n## Tỉ trọng trên tổng\n\n> Mỗi phòng ban chiếm bao nhiêu phần trăm quỹ lương?\n\n```sql\nSELECT department,\n       SUM(salary) AS payroll,\n       ROUND(100.0 * SUM(salary) / (SELECT SUM(salary) FROM employees), 1) AS percent\nFROM employees\nGROUP BY department\nORDER BY payroll DESC;\n```\n\n## Subquery phụ thuộc từng dòng\n\nSubquery trong SELECT có thể tham chiếu tới dòng đang xét, ví dụ số đơn của từng khách:\n\n```sql\nSELECT c.name,\n       (SELECT COUNT(*) FROM orders o WHERE o.customer_id = c.id) AS orders\nFROM customers c\nORDER BY orders DESC;\n```\n\nĐây là **subquery tương quan**, sẽ học kỹ ở chương 3. Với cột kiểu này, LEFT JOIN và GROUP BY thường nhanh hơn trên bảng lớn.\n\n## Thử ngay\n\nÔ thứ nhất tính tỉ trọng quỹ lương của từng phòng ban. Ô thứ hai đếm số đơn của từng khách bằng subquery tương quan; để ý ba khách có 0 đơn vẫn xuất hiện.', 3, 10, '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e004-0000-7000-8000-400000000004'), UUID_TO_BIN('01a1e004-0000-7000-8000-300000000002'), UUID_TO_BIN('01a1e004-0000-7000-8000-500000000004'), 'in-voi-subquery', 'IN với subquery', '## Thuộc danh sách do truy vấn khác tạo ra\n\n> Những sản phẩm mà khách Trần Bình (id 2) đã mua.\n\n```sql\nSELECT name\nFROM products\nWHERE id IN (\n    SELECT oi.product_id\n    FROM order_items oi\n    JOIN orders o ON o.id = oi.order_id\n    WHERE o.customer_id = 2\n);\n```\n\nSubquery trả một cột gồm nhiều giá trị, `IN` kiểm tra mỗi sản phẩm có nằm trong danh sách đó không.\n\n## IN hay JOIN\n\nCùng câu hỏi viết bằng JOIN:\n\n```sql\nSELECT DISTINCT p.name\nFROM products p\nJOIN order_items oi ON oi.product_id = p.id\nJOIN orders o ON o.id = oi.order_id\nWHERE o.customer_id = 2;\n```\n\nJOIN cần DISTINCT nếu khách mua một sản phẩm nhiều lần, còn IN tự nhiên không bị trùng. Khi chỉ cần **lọc** theo bảng khác mà không cần lấy cột của nó, IN (hoặc EXISTS) thường dễ đọc hơn.\n\n## Subquery phải trả đúng một cột\n\n`WHERE id IN (SELECT product_id, quantity FROM ...)` báo lỗi vì IN so một cột với một cột.\n\n## Thử ngay\n\nÔ dưới tìm khách đã từng mua sản phẩm thuộc danh mục Sách lập trình (id 11).', 1, 10, '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e004-0000-7000-8000-400000000005'), UUID_TO_BIN('01a1e004-0000-7000-8000-300000000002'), UUID_TO_BIN('01a1e004-0000-7000-8000-500000000005'), 'not-in-va-bay-null', 'NOT IN và cái bẫy NULL', '## Câu trả lời trống bất ngờ\n\n> Những nhân viên không quản lý ai.\n\nCách nghĩ tự nhiên: lấy những ai có id không nằm trong danh sách manager_id.\n\n```sql\nSELECT name\nFROM employees\nWHERE id NOT IN (SELECT manager_id FROM employees);\n```\n\nKết quả: **0 dòng**. Trong khi rõ ràng có 7 người không quản lý ai.\n\n## Vì sao\n\nDanh sách `SELECT manager_id FROM employees` chứa một **NULL** (giám đốc không có quản lý). `x NOT IN (1, 2, NULL)` tương đương `x <> 1 AND x <> 2 AND x <> NULL`. Vế cuối không bao giờ đúng, nên cả biểu thức không bao giờ đúng, với **mọi** x.\n\nChỉ cần một NULL trong danh sách, NOT IN trả rỗng.\n\n## Cách sửa\n\nLoại NULL trong subquery:\n\n```sql\nSELECT name\nFROM employees\nWHERE id NOT IN (SELECT manager_id FROM employees WHERE manager_id IS NOT NULL);\n```\n\nHoặc dùng `NOT EXISTS` (bài sau), cách an toàn với NULL mà người viết SQL kinh nghiệm thường chọn.\n\n## IN không bị ảnh hưởng\n\n`IN` vẫn đúng khi danh sách có NULL: `3 IN (1, 3, NULL)` vẫn đúng nhờ vế `3 = 3`. Chỉ `NOT IN` mới nguy hiểm.\n\n## Thử ngay\n\nChạy hai ô và so sánh.', 2, 14, '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e004-0000-7000-8000-400000000006'), UUID_TO_BIN('01a1e004-0000-7000-8000-300000000002'), UUID_TO_BIN('01a1e004-0000-7000-8000-500000000006'), 'any-va-all', 'So sánh với ANY và ALL', '## ALL: hơn mọi giá trị\n\n> Sản phẩm đắt hơn **mọi** điện thoại (danh mục 2).\n\n```sql\nSELECT name, price\nFROM products\nWHERE price > ALL (SELECT price FROM products WHERE category_id = 2);\n```\n\nĐiện thoại đắt nhất là iPhone 15 giá 22 triệu, nên kết quả là MacBook Air M3 và ThinkPad X1. `> ALL` tương đương `> (SELECT MAX(...))`.\n\n## ANY: hơn ít nhất một giá trị\n\n```sql\nSELECT name, price\nFROM products\nWHERE category_id <> 2\n  AND price > ANY (SELECT price FROM products WHERE category_id = 2);\n```\n\n`> ANY` tương đương `> (SELECT MIN(...))`. `= ANY` chính là `IN`.\n\n## Nên dùng khi nào\n\nANY và ALL ít gặp hơn MIN, MAX vì khó đọc hơn. Nhưng bạn sẽ gặp chúng trong code người khác, và cần biết `<> ALL` có cùng bẫy NULL với `NOT IN`.\n\n## Thử ngay\n\nÔ dưới tìm nhân viên lương cao hơn mọi người ở phòng Nhân sự.', 3, 10, '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e004-0000-7000-8000-400000000007'), UUID_TO_BIN('01a1e004-0000-7000-8000-300000000003'), UUID_TO_BIN('01a1e004-0000-7000-8000-500000000007'), 'subquery-tuong-quan', 'Subquery tương quan', '## So với nhóm của chính mình\n\n> Nhân viên lương cao hơn trung bình **phòng mình**.\n\nMỗi người cần so với một con số khác nhau, tuỳ phòng ban. Subquery tham chiếu tới cột của truy vấn ngoài:\n\n```sql\nSELECT e.name, e.department, e.salary\nFROM employees e\nWHERE e.salary > (\n    SELECT AVG(x.salary)\n    FROM employees x\n    WHERE x.department = e.department\n)\nORDER BY e.department, e.salary DESC;\n```\n\n`x.department = e.department` nối subquery với **dòng đang xét** `e`. Đây là subquery tương quan: về mặt logic, nó chạy lại cho từng nhân viên.\n\n## Đọc từ ngoài vào trong\n\n1. Lấy một nhân viên `e`, ví dụ Đinh Lực ở phòng Kỹ thuật.\n2. Tính trung bình lương phòng Kỹ thuật: 24,6 triệu.\n3. 28 triệu lớn hơn 24,6 triệu, nên giữ Đinh Lực.\n4. Lặp lại với người tiếp theo.\n\n## Bí danh là bắt buộc\n\nHai lần dùng bảng employees phải có hai bí danh khác nhau. Nếu viết `WHERE department = department`, điều kiện luôn đúng và bạn so với trung bình toàn công ty mà không hay biết.\n\n## Hiệu năng\n\nDatabase hiện đại thường tự viết lại subquery tương quan thành JOIN. Nhưng với bảng lớn, cách viết bằng CTE hoặc window function (hai chặng cuối) thường rõ ràng và nhanh hơn.\n\n## Thử ngay\n\nÔ dưới tìm sản phẩm đắt nhất trong từng danh mục.', 1, 14, '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e004-0000-7000-8000-400000000008'), UUID_TO_BIN('01a1e004-0000-7000-8000-300000000003'), UUID_TO_BIN('01a1e004-0000-7000-8000-500000000008'), 'exists', 'EXISTS: có ít nhất một dòng hay không', '## Chỉ cần biết có hay không\n\n> Những khách từng có đơn bị huỷ.\n\n```sql\nSELECT c.name\nFROM customers c\nWHERE EXISTS (\n    SELECT 1\n    FROM orders o\n    WHERE o.customer_id = c.id AND o.status = ''CANCELLED''\n);\n```\n\n`EXISTS (subquery)` đúng khi subquery trả **ít nhất một dòng**. Nó không quan tâm subquery chọn cột gì, nên người ta quen viết `SELECT 1`.\n\nKết quả: Lê Chi, Hoàng Em, Bùi Khánh.\n\n## Vì sao EXISTS hiệu quả\n\nDatabase dừng ngay khi tìm thấy dòng đầu tiên thoả điều kiện, không cần đọc hết. Với câu hỏi "có từng ... không", EXISTS là lựa chọn tự nhiên.\n\n## EXISTS không làm nhân dòng\n\nViết bằng JOIN, một khách có hai đơn huỷ sẽ xuất hiện hai lần. EXISTS chỉ lọc, mỗi khách xuất hiện tối đa một lần.\n\n## Thử ngay\n\nÔ dưới tìm danh mục có ít nhất một sản phẩm giá trên 10 triệu.', 2, 12, '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e004-0000-7000-8000-400000000009'), UUID_TO_BIN('01a1e004-0000-7000-8000-300000000003'), UUID_TO_BIN('01a1e004-0000-7000-8000-500000000009'), 'not-exists', 'NOT EXISTS: chưa từng có', '## Câu trả lời đúng cho bài NOT IN\n\n```sql\nSELECT e.name\nFROM employees e\nWHERE NOT EXISTS (\n    SELECT 1\n    FROM employees r\n    WHERE r.manager_id = e.id\n);\n```\n\nKết quả: 7 nhân viên không quản lý ai. NOT EXISTS so sánh từng dòng bằng `=` bên trong subquery, nên NULL của giám đốc không phá được kết quả.\n\n## Ba cách cho câu hỏi "chưa từng"\n\nKhách chưa từng đặt hàng:\n\n```sql\nSELECT c.name\nFROM customers c\nWHERE NOT EXISTS (SELECT 1 FROM orders o WHERE o.customer_id = c.id);\n```\n\n```sql\nSELECT c.name\nFROM customers c\nLEFT JOIN orders o ON o.customer_id = c.id\nWHERE o.id IS NULL;\n```\n\n```sql\nSELECT c.name\nFROM customers c\nWHERE c.id NOT IN (SELECT customer_id FROM orders);\n```\n\nCả ba cho Mai Quân, Trịnh Sơn, Cao Thảo, nhưng chỉ vì `orders.customer_id` không có NULL. Nên chọn NOT EXISTS hoặc LEFT JOIN, tránh NOT IN.\n\n## Thử ngay\n\nÔ dưới tìm khách chưa từng mua sản phẩm điện thoại (danh mục 2).', 3, 12, '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e004-0000-7000-8000-400000000010'), UUID_TO_BIN('01a1e004-0000-7000-8000-300000000004'), UUID_TO_BIN('01a1e004-0000-7000-8000-500000000010'), 'bang-dan-xuat', 'Bảng dẫn xuất: tính trước, lọc sau', '## Dùng kết quả như một bảng\n\nSubquery trong FROM tạo một **bảng dẫn xuất** (derived table). Bắt buộc phải đặt bí danh cho nó:\n\n```sql\nSELECT t.order_id, t.order_total\nFROM (\n    SELECT order_id, SUM(quantity * unit_price) AS order_total\n    FROM order_items\n    GROUP BY order_id\n) AS t\nWHERE t.order_total > 20000000\nORDER BY t.order_total DESC;\n```\n\n## Tổng hợp hai tầng\n\n> Giá trị trung bình của một đơn đã giao.\n\nBước 1 tính tổng mỗi đơn, bước 2 lấy trung bình các tổng đó:\n\n```sql\nSELECT ROUND(AVG(order_total)) AS avg_order_value\nFROM (\n    SELECT o.id, SUM(oi.quantity * oi.unit_price) AS order_total\n    FROM orders o\n    JOIN order_items oi ON oi.order_id = o.id\n    WHERE o.status = ''DELIVERED''\n    GROUP BY o.id\n) AS per_order;\n```\n\nKhông viết được `AVG(SUM(...))` trong một tầng: hàm tổng hợp không lồng nhau.\n\n## Nối bảng dẫn xuất với bảng thật\n\n```sql\nSELECT c.name, s.orders, s.last_order\nFROM customers c\nJOIN (\n    SELECT customer_id, COUNT(*) AS orders, MAX(order_date) AS last_order\n    FROM orders\n    GROUP BY customer_id\n) AS s ON s.customer_id = c.id\nORDER BY s.orders DESC;\n```\n\nGom nhóm trên orders **trước** khi nối giúp tránh hiện tượng nhân dòng.\n\n## Thử ngay\n\nÔ dưới tìm khách có đơn lớn nhất trên 25 triệu, kèm giá trị đơn đó.', 1, 14, '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e004-0000-7000-8000-400000000011'), UUID_TO_BIN('01a1e004-0000-7000-8000-300000000004'), UUID_TO_BIN('01a1e004-0000-7000-8000-500000000011'), 'chon-cach-viet', 'Chọn JOIN, subquery hay EXISTS', '## Mỗi công cụ hợp một kiểu câu hỏi\n\n- **Cần lấy cột** từ bảng khác để hiển thị: JOIN.\n- **Chỉ cần lọc** theo việc có hay không có dòng ở bảng khác: EXISTS, NOT EXISTS (hoặc IN).\n- **So với một giá trị tổng hợp**: subquery một giá trị.\n- **Tổng hợp nhiều tầng** hoặc tính trước rồi nối: bảng dẫn xuất, hoặc CTE ở chặng sau.\n\n## Một câu hỏi, nhiều cách\n\n> Khách ở Hà Nội đã từng mua laptop (danh mục 4).\n\n```sql\nSELECT DISTINCT c.name\nFROM customers c\nJOIN orders o ON o.customer_id = c.id\nJOIN order_items oi ON oi.order_id = o.id\nJOIN products p ON p.id = oi.product_id\nWHERE c.city = ''Hà Nội'' AND p.category_id = 4;\n```\n\n```sql\nSELECT c.name\nFROM customers c\nWHERE c.city = ''Hà Nội''\n  AND EXISTS (\n      SELECT 1\n      FROM orders o\n      JOIN order_items oi ON oi.order_id = o.id\n      JOIN products p ON p.id = oi.product_id\n      WHERE o.customer_id = c.id AND p.category_id = 4\n  );\n```\n\nCách EXISTS nói đúng ý câu hỏi ("đã từng") và không cần DISTINCT.\n\n## Tiêu chí chọn\n\n1. **Đúng** trước, kể cả với NULL và dòng trùng.\n2. **Dễ đọc** cho người sau.\n3. **Nhanh**: chỉ tối ưu khi đo thấy chậm.\n\n## Tổng kết chặng\n\nSubquery cho phép xây câu trả lời từng bước. Khi các bước nhiều lên, ngoặc lồng ngoặc trở nên khó đọc. Chặng tiếp theo, **SQL 5: CTE**, đặt tên cho từng bước để truy vấn dài vẫn rõ ràng.\n\n## Thử ngay\n\nÔ dưới viết lại bằng EXISTS. Thử đổi sang danh mục 6 (Phụ kiện).', 2, 12, '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000');
INSERT INTO lesson_cells (id, lesson_id, cell_key, position, starter_sql, dialect, dataset_version_id, dataset_variant_id, dataset_checksum, created_at, updated_at) VALUES
    (UUID_TO_BIN('01a1e004-0000-7000-8000-600000000001'), UUID_TO_BIN('01a1e004-0000-7000-8000-400000000001'), UUID_TO_BIN('01a1e004-0000-7000-8000-700000000001'), 1, 'SELECT name, department, salary\nFROM employees\nWHERE salary > (SELECT AVG(salary) FROM employees)\nORDER BY salary DESC;', 'POSTGRESQL', UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d02'), UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d03'), 'b9e493a8886c9ecb9e24ba075d73d685c07d83fba6f75b1a8906f609f317d58b', '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e004-0000-7000-8000-600000000002'), UUID_TO_BIN('01a1e004-0000-7000-8000-400000000002'), UUID_TO_BIN('01a1e004-0000-7000-8000-700000000002'), 1, 'SELECT id, customer_id, order_date\nFROM orders\nWHERE order_date = (SELECT MAX(order_date) FROM orders);', 'POSTGRESQL', UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d02'), UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d03'), 'b9e493a8886c9ecb9e24ba075d73d685c07d83fba6f75b1a8906f609f317d58b', '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e004-0000-7000-8000-600000000003'), UUID_TO_BIN('01a1e004-0000-7000-8000-400000000002'), UUID_TO_BIN('01a1e004-0000-7000-8000-700000000003'), 2, 'SELECT name, hire_date\nFROM employees\nWHERE hire_date > (SELECT hire_date FROM employees WHERE name = ''Hồ Vân'')\nORDER BY hire_date;', 'POSTGRESQL', UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d02'), UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d03'), 'b9e493a8886c9ecb9e24ba075d73d685c07d83fba6f75b1a8906f609f317d58b', '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e004-0000-7000-8000-600000000004'), UUID_TO_BIN('01a1e004-0000-7000-8000-400000000003'), UUID_TO_BIN('01a1e004-0000-7000-8000-700000000004'), 1, 'SELECT department,\n       SUM(salary) AS payroll,\n       ROUND(100.0 * SUM(salary) / (SELECT SUM(salary) FROM employees), 1) AS percent\nFROM employees\nGROUP BY department\nORDER BY payroll DESC;', 'POSTGRESQL', UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d02'), UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d03'), 'b9e493a8886c9ecb9e24ba075d73d685c07d83fba6f75b1a8906f609f317d58b', '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e004-0000-7000-8000-600000000005'), UUID_TO_BIN('01a1e004-0000-7000-8000-400000000003'), UUID_TO_BIN('01a1e004-0000-7000-8000-700000000005'), 2, 'SELECT c.name,\n       (SELECT COUNT(*) FROM orders o WHERE o.customer_id = c.id) AS orders\nFROM customers c\nORDER BY orders DESC, c.name;', 'POSTGRESQL', UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d02'), UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d03'), 'b9e493a8886c9ecb9e24ba075d73d685c07d83fba6f75b1a8906f609f317d58b', '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e004-0000-7000-8000-600000000006'), UUID_TO_BIN('01a1e004-0000-7000-8000-400000000004'), UUID_TO_BIN('01a1e004-0000-7000-8000-700000000006'), 1, 'SELECT name, city\nFROM customers\nWHERE id IN (\n    SELECT o.customer_id\n    FROM orders o\n    JOIN order_items oi ON oi.order_id = o.id\n    JOIN products p ON p.id = oi.product_id\n    WHERE p.category_id = 11\n);', 'POSTGRESQL', UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d02'), UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d03'), 'b9e493a8886c9ecb9e24ba075d73d685c07d83fba6f75b1a8906f609f317d58b', '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e004-0000-7000-8000-600000000007'), UUID_TO_BIN('01a1e004-0000-7000-8000-400000000005'), UUID_TO_BIN('01a1e004-0000-7000-8000-700000000007'), 1, 'SELECT name\nFROM employees\nWHERE id NOT IN (SELECT manager_id FROM employees);', 'POSTGRESQL', UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d02'), UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d03'), 'b9e493a8886c9ecb9e24ba075d73d685c07d83fba6f75b1a8906f609f317d58b', '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e004-0000-7000-8000-600000000008'), UUID_TO_BIN('01a1e004-0000-7000-8000-400000000005'), UUID_TO_BIN('01a1e004-0000-7000-8000-700000000008'), 2, 'SELECT name\nFROM employees\nWHERE id NOT IN (SELECT manager_id FROM employees WHERE manager_id IS NOT NULL);', 'POSTGRESQL', UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d02'), UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d03'), 'b9e493a8886c9ecb9e24ba075d73d685c07d83fba6f75b1a8906f609f317d58b', '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e004-0000-7000-8000-600000000009'), UUID_TO_BIN('01a1e004-0000-7000-8000-400000000006'), UUID_TO_BIN('01a1e004-0000-7000-8000-700000000009'), 1, 'SELECT name, department, salary\nFROM employees\nWHERE salary > ALL (SELECT salary FROM employees WHERE department = ''Nhân sự'')\nORDER BY salary;', 'POSTGRESQL', UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d02'), UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d03'), 'b9e493a8886c9ecb9e24ba075d73d685c07d83fba6f75b1a8906f609f317d58b', '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e004-0000-7000-8000-600000000010'), UUID_TO_BIN('01a1e004-0000-7000-8000-400000000007'), UUID_TO_BIN('01a1e004-0000-7000-8000-700000000010'), 1, 'SELECT p.name, p.category_id, p.price\nFROM products p\nWHERE p.price = (\n    SELECT MAX(x.price)\n    FROM products x\n    WHERE x.category_id = p.category_id\n)\nORDER BY p.category_id;', 'POSTGRESQL', UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d02'), UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d03'), 'b9e493a8886c9ecb9e24ba075d73d685c07d83fba6f75b1a8906f609f317d58b', '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e004-0000-7000-8000-600000000011'), UUID_TO_BIN('01a1e004-0000-7000-8000-400000000008'), UUID_TO_BIN('01a1e004-0000-7000-8000-700000000011'), 1, 'SELECT cat.name\nFROM categories cat\nWHERE EXISTS (\n    SELECT 1\n    FROM products p\n    WHERE p.category_id = cat.id AND p.price > 10000000\n);', 'POSTGRESQL', UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d02'), UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d03'), 'b9e493a8886c9ecb9e24ba075d73d685c07d83fba6f75b1a8906f609f317d58b', '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e004-0000-7000-8000-600000000012'), UUID_TO_BIN('01a1e004-0000-7000-8000-400000000009'), UUID_TO_BIN('01a1e004-0000-7000-8000-700000000012'), 1, 'SELECT c.name\nFROM customers c\nWHERE NOT EXISTS (\n    SELECT 1\n    FROM orders o\n    JOIN order_items oi ON oi.order_id = o.id\n    JOIN products p ON p.id = oi.product_id\n    WHERE o.customer_id = c.id AND p.category_id = 2\n)\nORDER BY c.name;', 'POSTGRESQL', UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d02'), UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d03'), 'b9e493a8886c9ecb9e24ba075d73d685c07d83fba6f75b1a8906f609f317d58b', '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e004-0000-7000-8000-600000000013'), UUID_TO_BIN('01a1e004-0000-7000-8000-400000000010'), UUID_TO_BIN('01a1e004-0000-7000-8000-700000000013'), 1, 'SELECT o.customer_id, MAX(t.order_total) AS biggest_order\nFROM (\n    SELECT order_id, SUM(quantity * unit_price) AS order_total\n    FROM order_items\n    GROUP BY order_id\n) AS t\nJOIN orders o ON o.id = t.order_id\nGROUP BY o.customer_id\nHAVING MAX(t.order_total) > 25000000\nORDER BY biggest_order DESC;', 'POSTGRESQL', UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d02'), UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d03'), 'b9e493a8886c9ecb9e24ba075d73d685c07d83fba6f75b1a8906f609f317d58b', '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e004-0000-7000-8000-600000000014'), UUID_TO_BIN('01a1e004-0000-7000-8000-400000000011'), UUID_TO_BIN('01a1e004-0000-7000-8000-700000000014'), 1, 'SELECT c.name\nFROM customers c\nWHERE c.city = ''Hà Nội''\n  AND EXISTS (\n      SELECT 1\n      FROM orders o\n      JOIN order_items oi ON oi.order_id = o.id\n      JOIN products p ON p.id = oi.product_id\n      WHERE o.customer_id = c.id AND p.category_id = 4\n  );', 'POSTGRESQL', UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d02'), UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d03'), 'b9e493a8886c9ecb9e24ba075d73d685c07d83fba6f75b1a8906f609f317d58b', '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000');
INSERT INTO quiz_questions (id, lesson_id, question_key, prompt, is_multiple, position, created_at, updated_at) VALUES
    (UUID_TO_BIN('01a1e004-0000-7000-8000-800000000001'), UUID_TO_BIN('01a1e004-0000-7000-8000-400000000001'), UUID_TO_BIN('01a1e004-0000-7000-8000-900000000001'), 'Vì sao WHERE price > AVG(price) báo lỗi?', FALSE, 1, '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e004-0000-7000-8000-800000000002'), UUID_TO_BIN('01a1e004-0000-7000-8000-400000000001'), UUID_TO_BIN('01a1e004-0000-7000-8000-900000000002'), 'Subquery (SELECT AVG(price) FROM products) trả về gì?', FALSE, 2, '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e004-0000-7000-8000-800000000003'), UUID_TO_BIN('01a1e004-0000-7000-8000-400000000002'), UUID_TO_BIN('01a1e004-0000-7000-8000-900000000003'), 'WHERE price = (SELECT MAX(price) ...) khác ORDER BY price DESC LIMIT 1 ở điểm nào?', FALSE, 1, '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e004-0000-7000-8000-800000000004'), UUID_TO_BIN('01a1e004-0000-7000-8000-400000000002'), UUID_TO_BIN('01a1e004-0000-7000-8000-900000000004'), 'Subquery dùng với dấu > trả về 3 dòng thì điều gì xảy ra?', FALSE, 2, '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e004-0000-7000-8000-800000000005'), UUID_TO_BIN('01a1e004-0000-7000-8000-400000000003'), UUID_TO_BIN('01a1e004-0000-7000-8000-900000000005'), 'Subquery trong SELECT phải thoả điều kiện gì?', FALSE, 1, '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e004-0000-7000-8000-800000000006'), UUID_TO_BIN('01a1e004-0000-7000-8000-400000000003'), UUID_TO_BIN('01a1e004-0000-7000-8000-900000000006'), 'Trong subquery đếm số đơn, o.customer_id = c.id tham chiếu tới đâu?', FALSE, 2, '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e004-0000-7000-8000-800000000007'), UUID_TO_BIN('01a1e004-0000-7000-8000-400000000004'), UUID_TO_BIN('01a1e004-0000-7000-8000-900000000007'), 'Subquery dùng với IN phải trả bao nhiêu cột?', FALSE, 1, '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e004-0000-7000-8000-800000000008'), UUID_TO_BIN('01a1e004-0000-7000-8000-400000000004'), UUID_TO_BIN('01a1e004-0000-7000-8000-900000000008'), 'Vì sao cách viết bằng JOIN thường cần DISTINCT trong ví dụ này?', FALSE, 2, '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e004-0000-7000-8000-800000000009'), UUID_TO_BIN('01a1e004-0000-7000-8000-400000000005'), UUID_TO_BIN('01a1e004-0000-7000-8000-900000000009'), 'Vì sao WHERE id NOT IN (SELECT manager_id FROM employees) trả 0 dòng?', FALSE, 1, '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e004-0000-7000-8000-800000000010'), UUID_TO_BIN('01a1e004-0000-7000-8000-400000000005'), UUID_TO_BIN('01a1e004-0000-7000-8000-900000000010'), 'Cách nào an toàn khi danh sách có thể chứa NULL?', TRUE, 2, '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e004-0000-7000-8000-800000000011'), UUID_TO_BIN('01a1e004-0000-7000-8000-400000000006'), UUID_TO_BIN('01a1e004-0000-7000-8000-900000000011'), 'price > ALL (subquery) tương đương cách viết nào?', FALSE, 1, '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e004-0000-7000-8000-800000000012'), UUID_TO_BIN('01a1e004-0000-7000-8000-400000000006'), UUID_TO_BIN('01a1e004-0000-7000-8000-900000000012'), '= ANY (subquery) tương đương gì?', FALSE, 2, '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
